steps.cmd:
case "$(uname -m)" in
  x86_64|amd64) resource_arch=x86_64 ;;
  aarch64|arm64) resource_arch=aarch64 ;;
  *) echo "Unsupported architecture: $(uname -m)"; exit 1 ;;
esac
server="$install_root/cc-switch-server"
mkdir -p "$install_root/bin"

chmod +x "$server"
launcher="$install_root/bin/ccswitch-kite"
cat > "$launcher" <<'SH'
#!/usr/bin/env bash
set -e
resource_root=/workspace/.kf/software/kite.cc-switch.web
server=$resource_root/cc-switch-server
runtime_dir=$resource_root/runtime
pid_file=$runtime_dir/cc-switch-web.pid
log_file=$runtime_dir/cc-switch-web.log
host=${CC_SWITCH_WEB_HOST:-127.0.0.1}
port=${2:-8766}
web_user=${CC_SWITCH_WEB_USER:-admin}
web_pass=${CC_SWITCH_WEB_PASSWORD:-kite-local}
home_dir=${CC_SWITCH_HOME:-${HOME:-/root}}
ensure_credentials() {
  mkdir -p "$home_dir/.cc-switch"
  printf '%s\n' "$web_user" > "$home_dir/.cc-switch/web_username"
  printf '%s\n' "$web_pass" > "$home_dir/.cc-switch/web_password"
  chmod 600 "$home_dir/.cc-switch/web_username" "$home_dir/.cc-switch/web_password" 2>/dev/null || true
}
is_running() {
  pid=$(cat "$pid_file" 2>/dev/null || true)
  [ -n "${pid:-}" ] && kill -0 "$pid" 2>/dev/null
}
case "${1:-start}" in
  start)
    mkdir -p "$runtime_dir"
    ensure_credentials
    if is_running; then echo "already_running http://$host:$port"; exit 0; fi
    command -v setsid >/dev/null 2>&1 || { echo 'missing setsid'; exit 127; }
    rm -f "$pid_file"
    echo "KITE_RESOURCE_STEP start-server $host:$port"
    HOME="$home_dir" HOST="$host" PORT="$port" ENABLE_HSTS=false setsid "$server" >> "$log_file" 2>&1 < /dev/null &
    echo $! > "$pid_file"
    for i in $(seq 1 30); do
      if curl -fsS -u "$web_user:$web_pass" "http://$host:$port/" >/dev/null 2>&1; then echo "ready http://$host:$port"; exit 0; fi
      if ! is_running; then echo 'cc-switch-web exited'; tail -40 "$log_file" || true; exit 1; fi
      sleep 1
    done
    echo 'cc-switch-web did not become ready'; tail -40 "$log_file" || true; exit 1 ;;
  stop) if is_running; then kill "$(cat "$pid_file")" || true; fi; rm -f "$pid_file"; echo stopped ;;
  status) if is_running; then echo "running http://$host:$port"; else echo stopped; exit 1; fi ;;
  password) ensure_credentials; echo "user $web_user"; echo "password $web_pass" ;;
  --help|-h|help) echo 'usage: ccswitch-kite start PORT/status PORT/stop/password' ;;
  *) echo 'usage: ccswitch-kite start PORT/status PORT/stop/password'; exit 2 ;;
esac
SH
chmod +x "$launcher"
